import { Helmet } from "react-helmet";
import '../styles/contactus.css';

function ContactUs() {
  return (
    <>
      <Helmet>
        <title>Contact Us | WE4HIM CBO</title>
        <meta
          name="description"
          content="Contact Us, help our misson to empower boys and men."
        />
      </Helmet>

      <div className="contact">
        <h2>Contact Us</h2>
        <p>Phone: +254 786 115 629, +254 723 142 167</p>
        <p>Email: we4himcbo@gmail.com</p>
        <p>Facebook: cbo Weforhim</p>
        <p>X Space: @We4himcbo</p>
        <p>Facebook: @Cbo Weforhim</p>
      </div>
    </>
  );
}

export default ContactUs;
